     if (!b)
         return *out_size?-1:0;

     cp = (char *)b->data + b->idx;
     // E_INT and E_LONG are guaranteed single item queries
     int err = 0;
     *(int64_t *)out = c->vv->varint_get64(&cp,
                                           (char *)b->data + b->uncomp_size,
